text:
{
  "title_novice": "Приметы глин залива в керне",
  "summary": [
    {"text": "Нижняя часть разреза залива сложена глинами и алевролитами, которые осели из взвеси во время паводков.", "claims": ["c2"]},
    {"text": "В керне их узнают по полной биотурбации, редким участкам ленточной слоистости, растительным остаткам, смешанной фауне, конкрециям и сидериту.", "claims": ["c3", "c4", "c5", "c6"]},
    {"text": "Ни один признак не обязателен: слоистость иногда сохраняется, а конкреции часто, но не всегда.", "claims": ["c4", "c6"]}
  ],
  "claims": [
    {"key": "c1", "text": "Разрезы залива тонкие: мощность 4–10 м.", "kind": "observation", "unit_id": "u-034-31ed40", "page": 34, "quote": "Эти разрезы характеризуются небольшой мощностью (4–10м)", "numbers": ["4–10"], "question": null},
    {"key": "c2", "text": "Разрез начинается с аргиллитов и алевролитов, осевших из взвеси во время паводков.", "kind": "observation", "unit_id": "u-034-31ed40", "page": 34, "quote": "начинаются с аргиллитов — алевролитов, осажденных из взвеси в пределах всей внутридельтовой области во время паводковых периодов", "numbers": [], "question": null},
    {"key": "c3", "text": "Отложения залива полностью биотурбированы: осадок переработан организмами.", "kind": "observation", "unit_id": "u-034-31ed40", "page": 34, "quote": "Отложения полностью биотурбированы, но иногда сохраняется тонкая ленточная слоистость", "numbers": [], "question": null},
    {"key": "c4", "text": "Тонкая ленточная слоистость иногда всё же сохраняется.", "kind": "observation", "unit_id": "u-034-31ed40", "page": 34, "quote": "но иногда сохраняется тонкая ленточная слоистость", "numbers": [], "question": null},
    {"key": "c5", "text": "В глинах обильны растительные остатки и фауна солоноватой и пресной воды.", "kind": "observation", "unit_id": "u-034-31ed40", "page": 34, "quote": "обильны растительные остатки и солоновато- и пресноводная фауна", "numbers": [], "question": null},
    {"key": "c6", "text": "Часто встречаются конкреции или прослои сидерита.", "kind": "observation", "unit_id": "u-034-31ed40", "page": 34, "quote": "Часто встречаются конкреции или прослои сидерита.", "numbers": [], "question": null},
    {"key": "c7", "text": "Глины и алевролиты могут слагать весь разрез залива; обычно сверху есть песчаники.", "kind": "observation", "unit_id": "u-034-31ed40", "page": 34, "quote": "Аргиллиты и алевролиты могут слагать весь разрез заполненного залива, но обычно разрезы завершаются маломощными песчаниками намывных валов", "numbers": [], "question": null},
    {"key": "c8", "text": "Такие разрезы часто повторяются в серии и отражают повторные заполнения залива.", "kind": "inference", "unit_id": "u-034-31ed40", "page": 34, "quote": "которые часто встречаются в виде серии мелких разрезов регрессивного типа, отражающих повторные заполнения заливов", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Паводок приносит в залив взвесь — мелкие частицы, которые плавают в воде. Из неё оседают аргиллиты и алевролиты.", "claims": ["c2"], "hypothesis": false},
    {"text": "Тонкие частицы оседают там, где вода почти спокойна. Поэтому нижняя часть залива тонкозернистая.", "claims": ["c2"], "hypothesis": true},
    {"text": "Норы и ходы живых организмов перемешивают осадок уже после его накопления. Первичные слои частично стираются.", "claims": ["c3"], "hypothesis": true},
    {"text": "Слоистость сохраняется только там, где норы её не разрушили. Поэтому её видно редко, отдельными участками.", "claims": ["c4"], "hypothesis": true},
    {"text": "Растительные остатки и животные показывают, что в заливе была жизнь. Смешанная фауна — солоноватоводная и пресноводная.", "claims": ["c5"], "hypothesis": true}
  ],
  "practice": [
    {"text": "Начни описание с нижней части разреза. Там ожидаешь аргиллиты и алевролиты, осевшие из взвеси.", "claims": ["c2"], "hypothesis": false},
    {"text": "Оцени полноту биотурбации. Если слоистость почти стёрта норами, отмечай полную биотурбацию.", "claims": ["c3"], "hypothesis": false},
    {"text": "Поищи участки тонкой ленточной слоистости. Их немного, и в некоторых интервалах их нет.", "claims": ["c4"], "hypothesis": false},
    {"text": "Отмечай растительные остатки и фауну. Записывай отдельно солоноватоводных и пресноводных животных.", "claims": ["c5"], "hypothesis": false},
    {"text": "Записывай конкреции и прослои сидерита. Они часто встречаются, поэтому их отсутствие тоже стоит отметить.", "claims": ["c6"], "hypothesis": true},
    {"text": "Смотри верх разреза. Если песчаников нет, весь разрез может быть глинистым.", "claims": ["c7"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Признаки не обязаны присутствовать все. Ленточная слоистость иногда сохраняется, но не во всех разрезах.", "claims": ["c4"], "hypothesis": false},
    {"text": "Конкреции и сидерит часто встречаются, но это не обязательный признак. Без них вывод опирается на остальные признаки.", "claims": ["c6"], "hypothesis": true},
    {"text": "Аргиллиты и алевролиты могут занимать весь разрез заполненного залива. Тогда признаки видны по всей толще.", "claims": ["c7"], "hypothesis": false},
    {"text": "Автор отмечает смесь солоноватоводной и пресноводной фауны, но в этой части не объясняет её причину.", "claims": ["c5"], "hypothesis": false},
    {"text": "Такие разрезы повторяются в серии, отражая повторные заполнения залива.", "claims": ["c8"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Почему норы стирают слоистость", "text": "Организмы, роющие норы, разрушают первичные слои. Там, где их было много, слоистость почти не сохраняется.", "claims": ["c3", "c4"], "hypothesis": true},
    {"title": "Что может значить смешанная фауна", "text": "Солоноватоводные и пресноводные виды в одном разрезе могут отражать колебания солёности воды. Это гипотеза; глава вывода не даёт.", "claims": ["c5"], "hypothesis": true},
    {"title": "Сидерит и конкреции", "text": "Сидерит — карбонат железа (справка вне главы). Вместе с конкрециями он может отражать бедную кислородом среду — это гипотеза.", "claims": ["c6"], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Мощность разреза залива: 4–10 м.", "claims": ["c1"]},
    {"text": "Отложения полностью биотурбированы.", "claims": ["c3"]},
    {"text": "Ленточная слоистость: тонкая, сохраняется иногда.", "claims": ["c4"]},
    {"text": "Растительные остатки: обильны.", "claims": ["c5"]},
    {"text": "Конкреции или прослои сидерита: часто встречаются.", "claims": ["c6"]},
    {"text": "Верх разреза: обычно маломощные песчаники; возможен весь разрез из аргиллитов и алевролитов.", "claims": ["c7"]}
  ],
  "terms_defined": [
    {"term": "биотурбация", "term_en": "bioturbation", "abbr": "", "definition": "Перемешивание и разрушение первичных слоёв осадка живыми организмами, которые роют норы и ходы. В главе отложения названы полностью биотурбированными.", "claims": ["c3"]},
    {"term": "ленточная слоистость", "term_en": "ribbon bedding", "abbr": "", "definition": "Очень тонкие, почти параллельные слои, похожие на ленты. В главе такая слоистость сохраняется лишь иногда.", "claims": ["c4"]},
    {"term": "сидерит", "term_en": "siderite", "abbr": "", "definition": "Минерал, карбонат железа (справка вне главы). В главе указан как прослои в глинах залива, часто вместе с конкрециями.", "claims": ["c6"]},
    {"term": "конкреция", "term_en": "concretion", "abbr": "", "definition": "Плотное тело, выросшее внутри осадка из минерального вещества вокруг центра (общая справка). Здесь встречается часто.", "claims": ["c6"]}
  ],
